9	export default async function PosPage({
10	  params,
11	}: {
12	  params: Promise<{ businessId: string }>;
13	}) {
14	  const { businessId } = await params;
15	  const supabase = await createClient();
16	
17	  // business (DB) and the cashier session (a cookie read, not a query) don't
18	  // depend on each other — fire both at once instead of waiting in sequence.
19	  const [{ data: business }, session] = await Promise.all([
20	    supabase
21	      .from("businesses")
22	      .select(
23	        "id, name, business_type, tax_enabled, tax_rate, service_enabled, service_rate",
24	      )
25	      .eq("id", businessId)
26	      .single(),
27	    getCashierSession(businessId),
28	  ]);
29	
30	  if (!business) {
31	    notFound();
32	  }
33	
34	  if (!session) {
35	    const { data: cashiers } = await supabase
36	      .from("cashiers")
37	      .select("id, name, role")
38	      .eq("business_id", businessId)
39	      .eq("active", true)
40	      .order("created_at", { ascending: true });
41	
42	    return (
43	      <PinScreen
44	        businessId={businessId}
45	        businessName={business.name}
46	        cashiers={cashiers ?? []}
47	      />
48	    );
49	  }
50	
51	  const { data: activeShift } = await supabase
52	    .from("shifts")
53	    .select("id, opening_cash, opened_at")
54	    .eq("business_id", businessId)
55	    .is("closed_at", null)
56	    .maybeSingle();
57	
58	  if (!activeShift) {
59	    return (
60	      <OpenShiftScreen
61	        businessId={businessId}
62	        businessName={business.name}
63	        cashierId={session.cashierId}
64	        cashierName={session.name}
65	      />
66	    );
67	  }
68	
69	  if (business.business_type === "tiket") {
70	    const todayStr = new Date().toLocaleDateString("en-CA", { timeZone: "Asia/Jakarta" });
71	    const dayOfWeek = new Date(`${todayStr}T00:00:00`).getDay();
72	
73	    // None of these 4 queries depend on each other's results — run together.
74	    const [
75	      { data: categoryRows },
76	      { data: customPaymentMethodRowsForTiket },
77	      { data: memberRows },
78	      { data: holidayRow },
79	    ] = await Promise.all([
80	      supabase
81	        .from("ticket_categories")
82	        .select(
83	          "id, name, price_weekday, price_holiday, member_price, group_min_qty, group_price",
84	        )
85	        .eq("business_id", businessId)
86	        .eq("active", true)
87	        .is("deleted_at", null)
88	        .order("name", { ascending: true }),
89	      supabase
90	        .from("custom_payment_methods")
91	        .select("name")
92	        .eq("business_id", businessId)
93	        .order("name", { ascending: true }),
94	      supabase
95	        .from("members")
96	        .select("id, name, phone, member_code, valid_from, valid_until")
97	        .eq("business_id", businessId)
98	        .is("deleted_at", null)
99	        .order("name", { ascending: true }),
100	      supabase
101	        .from("ticket_holidays")
102	        .select("id")
103	        .eq("business_id", businessId)
104	        .eq("holiday_date", todayStr)
105	        .maybeSingle(),
106	    ]);
107	    const isHoliday = dayOfWeek === 0 || dayOfWeek === 6 || !!holidayRow;
108	
109	    return (
110	      <TicketPosScreen
111	        businessId={businessId}
112	        businessName={business.name}
113	        cashierId={session.cashierId}
114	        cashierName={session.name}
115	        shiftId={activeShift.id}
116	        categories={(categoryRows ?? []).map((c) => ({
117	          id: c.id,
118	          name: c.name,
119	          priceWeekday: Number(c.price_weekday),
120	          priceHoliday: Number(c.price_holiday),
121	          memberPrice: Number(c.member_price),
122	          groupMinQty: Number(c.group_min_qty),
123	          groupPrice: c.group_price == null ? null : Number(c.group_price),
124	        }))}
125	        members={(memberRows ?? []).map((m) => ({
126	          id: m.id,
127	          name: m.name,
128	          phone: m.phone,
129	          memberCode: m.member_code,
130	          validFrom: m.valid_from,
131	          validUntil: m.valid_until,
132	        }))}
133	        taxRate={business.tax_enabled ? Number(business.tax_rate) : 0}
134	        serviceRate={business.service_enabled ? Number(business.service_rate) : 0}
135	        isHoliday={isHoliday}
136	        customPaymentMethods={(customPaymentMethodRowsForTiket ?? []).map((m) => m.name)}
137	      />
138	    );
139	  }
140	
141	  const isFnb = business.business_type === "fnb";
142	
143	  // Same idea as the ticket branch above — these 4 queries are independent.
144	  const [
145	    { data: products },
146	    { data: openBillRows },
147	    { data: customers },
148	    { data: customPaymentMethodRows },
149	  ] = await Promise.all([
150	    supabase
151	      .from("products")
152	      .select("id, name, category, price, cost, stock, emoji, barcode, sku, variant_label")
153	      .eq("business_id", businessId)
154	      .is("deleted_at", null)
155	      .order("name", { ascending: true }),
156	    supabase
157	      .from("open_bills")
158	      .select("id, label, items, updated_at")
159	      .eq("business_id", businessId)
160	      .order("updated_at", { ascending: false }),
161	    supabase
162	      .from("customers")
163	      .select("id, name, phone")
164	      .eq("business_id", businessId)
165	      .is("deleted_at", null)
166	      .order("name", { ascending: true }),
167	    supabase
168	      .from("custom_payment_methods")
169	      .select("name")
170	      .eq("business_id", businessId)
171	      .order("name", { ascending: true }),
172	  ]);
173	
174	  let selfOrders: SelfOrderRow[] = [];
175	  if (isFnb) {
176	    const { data: orderRows } = await supabase
177	      .from("self_orders")
178	      .select(
179	        "id, status, created_at, tables(name), self_order_items(product_id, name, qty, price, note)",
180	      )
181	      .eq("business_id", businessId)
182	      .neq("status", "selesai")
183	      .order("created_at", { ascending: true });
184	    selfOrders = (orderRows ?? []) as unknown as SelfOrderRow[];
185	  }
186	
187	  return (
188	    <PosScreen
189	      businessId={businessId}
190	      businessName={business.name}
191	      cashierId={session.cashierId}
192	      cashierName={session.name}
193	      shiftId={activeShift.id}
194	      products={products ?? []}
195	      taxRate={business.tax_enabled ? Number(business.tax_rate) : 0}
196	      serviceRate={business.service_enabled ? Number(business.service_rate) : 0}
197	      openBills={(openBillRows ?? []) as unknown as OpenBillRow[]}
198	      customers={customers ?? []}
199	      isFnb={isFnb}
200	      customPaymentMethods={(customPaymentMethodRows ?? []).map((m) => m.name)}
201	      selfOrders={selfOrders.map((o) => ({
202	        id: o.id,
203	        status: o.status,
204	        createdAt: o.created_at,
205	        tableName: o.tables?.name ?? "Meja terhapus",
206	        items: o.self_order_items.map((i) => ({
207	          productId: i.product_id,
208	          name: i.name,
209	          qty: i.qty,
210	          price: i.price,
211	          note: i.note,
212	        })),
213	      }))}
214	    />
215	  );
216	}
