16	export async function verifyPin(
17	  businessId: string,
18	  cashierId: string,
19	  pin: string,
20	): Promise<{ success: boolean; error?: string }> {
21	  const supabase = await createClient();
22	  const { data, error } = await supabase
23	    .rpc("verify_cashier_pin", { p_cashier_id: cashierId, p_pin: pin })
24	    .single();
25	
26	  if (error || !data) {
27	    return { success: false, error: "PIN salah, coba lagi" };
28	  }
29	
30	  const cashier = data as VerifyCashierPinRow;
31	
32	  // Defensive check: this action is called with client-supplied arguments,
33	  // so don't trust businessId blindly even though the RPC already scopes
34	  // the cashier lookup to businesses the logged-in owner owns.
35	  if (cashier.business_id !== businessId) {
36	    return { success: false, error: "PIN salah, coba lagi" };
37	  }
38	
39	  await setCashierSession({
40	    cashierId: cashier.id,
41	    businessId: cashier.business_id,
42	    name: cashier.name,
43	    role: cashier.role,
44	  });
45	
46	  return { success: true };
47	}
