68	export async function checkout(
69	  businessId: string,
70	  cashierId: string,
71	  items: CartItemInput[],
72	  paymentMethod: string,
73	  received: number | null,
74	  orderDisc: number,
75	  orderDiscType: DiscountType,
76	  customerId: string | null = null,
77	  selfOrderIds: string[] = [],
78	): Promise<CheckoutResult> {
79	  if (items.length === 0) {
80	    return { success: false, error: "Keranjang masih kosong." };
81	  }
82	
83	  const supabase = await createClient();
84	  const { data, error } = await supabase
85	    .rpc("checkout_transaction", {
86	      p_business_id: businessId,
87	      p_cashier_id: cashierId,
88	      p_items: items.map((i) => ({
89	        product_id: i.productId,
90	        qty: i.qty,
91	        disc: i.disc,
92	        disc_type: i.discType,
93	      })),
94	      p_payment_method: paymentMethod,
95	      p_received: received,
96	      p_order_disc: orderDisc,
97	      p_order_disc_type: orderDiscType,
98	      p_customer_id: customerId,
99	      p_self_order_ids: selfOrderIds.length > 0 ? selfOrderIds : null,
100	    })
101	    .single();
102	
103	  if (error || !data) {
104	    return { success: false, error: error?.message ?? "Gagal memproses transaksi." };
105	  }
106	
107	  const result = data as CheckoutRpcRow;
108	  const itemCount = items.reduce((sum, i) => sum + i.qty, 0);
109	  await logActivity(
110	    supabase,
111	    businessId,
112	    "transaksi",
113	    "sukses",
114	    `Transaksi ${result.invoice_number}`,
115	    `${itemCount} item · ${paymentMethod}`,
116	  );
117	
118	  await printKitchenTicketsForItems(
119	    supabase,
120	    businessId,
121	    "Kasir",
122	    result.invoice_number,
123	    items.map((i) => ({ productId: i.productId, qty: i.qty })),
124	  );
125	
126	  return { success: true, invoiceNumber: result.invoice_number, transactionId: result.transaction_id };
127	}
